const paths=[{label:'CALL → ENTRY → B —Taken→ C —Taken→ END',note:'Requires x==0 and x!=0 with x unchanged: infeasible by additional reasoning.'},{label:'CALL → ENTRY → B —Taken→ C —Fallthrough→ END',note:'Conditions admit x==0 in this toy example.'},{label:'CALL → ENTRY → B —Fallthrough→ END',note:'Conditions admit x!=0 in this toy example.'}];function show(raw){let np=Number(raw);if(!Number.isFinite(np))return;np=Math.max(1,Math.min(5,Math.trunc(np)));document.getElementById('np').value=document.getElementById('np-range').value=np;const cap=np-1,n=Math.min(cap,paths.length),exhausted=n===paths.length;document.getElementById('toy-status').textContent='capacity = NP - 1 = '+cap+'\nreturned_count = '+n+' < '+np+'\ncoverage = '+(exhausted?'complete_within_declared_scope (structural toy graph)':'partial')+'\nenumeration_exhausted = '+exhausted+'\ntruncated = '+(!exhausted)+'\nstop_reason = '+(exhausted?'frontier-exhausted':'path-count-budget');const wrap=document.getElementById('toy-paths');wrap.replaceChildren();if(n===0){const p=document.createElement('p');p.textContent='The capacity is zero. This does not prove the graph has no path.';wrap.append(p);return}const table=document.createElement('table'),head=document.createElement('tr');for(const h of ['Retained structural path','Separate reasoning about data conditions']){const th=document.createElement('th');th.textContent=h;head.append(th)}table.append(head);for(const p of paths.slice(0,n)){const tr=document.createElement('tr'),a=document.createElement('td'),b=document.createElement('td');a.className='toy-path';a.textContent=p.label;b.textContent=p.note;tr.append(a,b);table.append(tr)}wrap.append(table)}document.getElementById('np').addEventListener('input',e=>show(e.target.value));document.getElementById('np-range').addEventListener('input',e=>show(e.target.value));show(2);
